```
```c
// minimal C impl sketch (no error paths)
#include <stdlib.h>
#include "pipeline.h"

struct Pipeline { int dummy; };
Pipeline* pipeline_create(const char* cfg){ (void)cfg; return (Pipeline*)malloc(sizeof(Pipeline)); }
void pipeline_destroy(Pipeline* p){ free(p); }
void pipeline_submit(Pipeline* p, const uint8_t* in, size_t len,
                     void (*done)(const uint8_t*, size_t, void*), void* ctx){
  // pretend processing and return a copied output asynchronously via callback
